UPDATE fin_stock_cost_layer
SET avg_unit_cost = #{avgUnitCost},
    stock_quantity = #{stockQuantity},
    stock_amount = #{stockAmount},
    version = version + 1,
    update_by = #{updateBy},
    update_time = NOW()
WHERE tenant_id = #{tenantId}
  AND dept_id = #{deptId}
  AND product_id = #{productId}
  AND version = #{version}

